#include <stdio.h>

int main() {
    char operator;
    float a, b;

    printf("Enter expression (e.g., 5 + 3): ");
    scanf("%f %c %f", &a, &operator, &b);

    switch (operator) {
        case '+':
            printf("%.2f + %.2f = %.2f\n", a, b, a + b);
            break;
        case '-':
            printf("%.2f - %.2f = %.2f\n", a, b, a - b);
            break;
        case '*':
            printf("%.2f * %.2f = %.2f\n", a, b, a * b);
            break;
        case '/':
            if (b != 0)
                printf("%.2f / %.2f = %.2f\n", a, b, a / b);
            else
                printf("Error: Division by zero!\n");
            break;
        default:
            printf("Invalid operator!\n");
    }

    return 0;
}

// Using for loop (when count is known)
for (int i = 1; i <= 5; i++) {
    printf("%d ", i);  // 1 2 3 4 5
}

// Using while loop (check before)
int i = 1;
while (i <= 5) {
    printf("%d ", i);  // 1 2 3 4 5
    i++;
}

// Using do-while loop (check after, runs at least once)
int j = 1;
do {
    printf("%d ", j);  // 1 2 3 4 5
    j++;
} while (j <= 5);

