#include <stdio.h>

// Call by value — changes don't affect original
void swapByValue(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
    // Only local copies are swapped — original unchanged
}

// Call by reference — changes DO affect original
void swapByReference(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
    // Original values are swapped via pointers
}

int main() {
    int x = 10, y = 20;

    printf("Before: x=%d, y=%d\n", x, y);  // 10, 20

    swapByValue(x, y);
    printf("After swapByValue: x=%d, y=%d\n", x, y);  // 10, 20 (unchanged!)

    swapByReference(&x, &y);  // pass addresses
    printf("After swapByReference: x=%d, y=%d\n", x, y);  // 20, 10 (swapped!)

    return 0;
}

#include <stdio.h>

// Recursive factorial: n! = n × (n-1)!
int factorial(int n) {
    if (n <= 1) return 1;       // base case: 0! = 1, 1! = 1
    return n * factorial(n - 1); // recursive call
}

/*  Call trace for factorial(4):
    factorial(4)
    = 4 * factorial(3)
    = 4 * 3 * factorial(2)
    = 4 * 3 * 2 * factorial(1)
    = 4 * 3 * 2 * 1
    = 24
*/

int main() {
    int n = 4;
    printf("%d! = %d\n", n, factorial(n));  // 4! = 24
    return 0;
}
